22	  double s123;
23	
24	  auto zab2 = [&za, &zb](int i1, int i2, int i3, int i4) { 
25	      return za(i1,i2)*zb(i2,i4) + za(i1,i3)*zb(i3,i4); 
26	  };
27	
28	
29	  s123 = s(j1, j2) + s(j2, j3) + s(j3, j1);
30	
31	  l12 = lnrat(musq, -s(j1, j2));
32	  l45 = lnrat(musq, -s(j4, j5));
33	  A5lom = za(j2, j4) * zab2(j2,j1,j3,j5) / (za(j2, j3) * za(j3, j1) * s123);
34	  Vcc = -(epinv * epinv2 + epinv * l12 + half * std::pow(l12, 2)) - two * (epinv + l45) - four;
35	  Fcc = -za(j2, j4) * zab2(j2,j1,j3,j5) / (za(j2, j3) * za(j3, j1) * s123)
36	        * Lsm1(-s(j1, j2), -s123, -s(j1, j3), -s123)
37	        + zab2(j2,j1,j3,j5) * (za(j1, j2) * za(j3, j4) - za(j1, j4) * za(j2, j3))
38	        / (za(j2, j3) * std::pow(za(j1, j3), 2) * s123)
39	        * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123)
40	        + two * zb(j1, j3) * za(j1, j4) * zab2(j2,j1,j3,j5) / (za(j1, j3) * s123)
41	        * L0(-s(j2, j3), -s123) / s123;
42	
43	  Vsc = half * (epinv + l45) + half;
44	  Fsc = za(j1, j4) * za(j2, j3) * zab2(j1,j2,j3,j5) / (std::pow(za(j1, j3), 3) * s123)
45	        * Lsm1(-s(j1, j2), -s123, -s(j2, j3), -s123)
46	        + half * za(j4, j1) * std::pow(zb(j1, j3), 2) * za(j2, j3) * zab2(j1,j2,j3,j5)
47	        / (za(j1, j3) * s123) * L1(-s123, -s(j2, j3)) / std::pow(s(j2, j3), 2)
48	        + za(j1, j4) * za(j2, j3) * zb(j3, j1) * zab2(j1,j2,j3,j5) 
49	        / (std::pow(za(j1, j3), 2) * s123) * L0(-s123, -s(j2, j3)) / s(j2, j3)
50	        - za(j2, j1) * zb(j1, j3) * za(j4, j3) * zb(j3, j5) / za(j1, j3)
51	        * L1(-s123, -s(j1, j2)) / std::pow(s(j1, j2), 2)
52	        - za(j2, j1) * zb(j1, j3) * za(j3, j4) * zab2(j1,j2,j3,j5)
53	        / (std::pow(za(j1, j3), 2) * s123) * L0(-s123, -s(j1, j2)) / s(j1, j2)
54	        + half * zab2(j4,j1,j2,j3) * (zb(j1, j3) * zb(j2, j5) + zb(j2, j3) * zb(j1, j5))
55	        / (zb(j1, j2) * zb(j2, j3) * za(j1, j3) * s123);
